CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE IF NOT EXISTS restaurants(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),name VARCHAR(160) NOT NULL,document VARCHAR(30),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),restaurant_id UUID NOT NULL REFERENCES restaurants(id),name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'WAITER',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),restaurant_id UUID NOT NULL REFERENCES restaurants(id),name VARCHAR(100) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS products(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),restaurant_id UUID NOT NULL REFERENCES restaurants(id),category_id UUID REFERENCES categories(id),name VARCHAR(160) NOT NULL,description TEXT,price NUMERIC(12,2) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ingredients(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),restaurant_id UUID NOT NULL REFERENCES restaurants(id),name VARCHAR(160) NOT NULL,unit VARCHAR(20) NOT NULL,current_quantity NUMERIC(14,3) NOT NULL DEFAULT 0,minimum_quantity NUMERIC(14,3) NOT NULL DEFAULT 0,cost_per_unit NUMERIC(12,4) NOT NULL DEFAULT 0,expiration_date DATE);
CREATE TABLE IF NOT EXISTS recipes(product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,ingredient_id UUID NOT NULL REFERENCES ingredients(id),quantity NUMERIC(14,3) NOT NULL,PRIMARY KEY(product_id,ingredient_id));
CREATE TABLE IF NOT EXISTS restaurant_tables(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),restaurant_id UUID NOT NULL REFERENCES restaurants(id),number INTEGER NOT NULL,seats INTEGER NOT NULL DEFAULT 4,status VARCHAR(30) NOT NULL DEFAULT 'AVAILABLE',UNIQUE(restaurant_id,number));
CREATE TABLE IF NOT EXISTS orders(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),restaurant_id UUID NOT NULL REFERENCES restaurants(id),table_id UUID REFERENCES restaurant_tables(id),user_id UUID REFERENCES users(id),customer_name VARCHAR(160),status VARCHAR(30) NOT NULL DEFAULT 'OPEN',payment_method VARCHAR(30),total NUMERIC(12,2) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),closed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS order_items(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id UUID NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL,unit_price NUMERIC(12,2) NOT NULL,notes TEXT);
CREATE TABLE IF NOT EXISTS cash_movements(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),restaurant_id UUID NOT NULL REFERENCES restaurants(id),type VARCHAR(20) NOT NULL,description VARCHAR(240) NOT NULL,amount NUMERIC(12,2) NOT NULL,payment_method VARCHAR(30),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_orders_restaurant_date ON orders(restaurant_id,created_at);CREATE INDEX IF NOT EXISTS idx_stock_restaurant ON ingredients(restaurant_id);
